import { v4 as uuidv4 } from 'uuid';
import { AppStatus, Chunk, Document } from '../shared/types';
import { PersistenceService } from './persistence-service';

const INDEX_META = 'index-meta.json';
const DOCUMENTS_META = 'documents-meta.json';
const CHUNKS_DIR = 'chunks';
export const CHUNK_SIZE = 500;

/** Map of documentId -> chunk ids for every indexed document. */
type IndexMeta = Record<string, string[]>;

export class IndexingService {
  private persistence: PersistenceService;
  private inProgress = false;
  private lastError = false;
  private lastActivity = '';

  constructor(persistence: PersistenceService) {
    this.persistence = persistence;
  }

  /** Index documents. If documentId is provided, index only that document; otherwise every un-indexed one. */
  async startIndexing(documentId?: string): Promise<AppStatus> {
    this.inProgress = true;
    this.lastError = false;
    try {
      const docs = this.readDocs();
      const meta = this.readMeta();
      const targets = documentId
        ? docs.filter(d => d.id === documentId)
        : docs.filter(d => !meta[d.id]);

      if (documentId && targets.length === 0) this.lastError = true;

      for (const doc of targets) {
        this.indexOne(doc, docs, meta);
      }

      this.persistence.writeJson(INDEX_META, meta);
      this.persistence.writeJson(DOCUMENTS_META, docs);
    } catch (err) {
      console.error('Indexing failed:', err);
      this.lastError = true;
    } finally {
      this.inProgress = false;
      this.lastActivity = new Date().toISOString();
    }
    return this.getStatus();
  }

  private indexOne(doc: Document, docs: Document[], meta: IndexMeta): void {
    const content = this.persistence.readText(`content/${doc.id}.txt`);
    if (content === null) {
      doc.status = 'error';
      this.lastError = true;
      return;
    }
    const chunks = this.chunkDocument(doc.id, content);
    this.persistence.writeJson(`${CHUNKS_DIR}/${doc.id}.json`, chunks);
    meta[doc.id] = chunks.map(c => c.id);
    const target = docs.find(d => d.id === doc.id);
    if (target) {
      target.status = 'indexed';
      target.chunks = chunks.length;
    }
  }

  /** Remove a document's chunks from the index (called on delete). */
  removeDocument(documentId: string): void {
    const meta = this.readMeta();
    delete meta[documentId];
    this.persistence.writeJson(INDEX_META, meta);
    this.persistence.deleteFile?.(`${CHUNKS_DIR}/${documentId}.json`);
    this.lastActivity = new Date().toISOString();
  }

  /** Get current indexing status, including progress counts. */
  getStatus(): AppStatus {
    const docs = this.readDocs();
    const meta = this.readMeta();
    const docIds = new Set(docs.map(d => d.id));
    const indexedIds = Object.keys(meta).filter(id => docIds.has(id));
    const totalChunks = indexedIds.reduce((n, id) => n + meta[id].length, 0);

    let indexStatus: AppStatus['indexStatus'];
    if (this.inProgress) indexStatus = 'indexing';
    else if (this.lastError || docs.some(d => d.status === 'error')) indexStatus = 'error';
    else if (docs.length > 0 && indexedIds.length === docs.length) indexStatus = 'ready';
    else indexStatus = 'idle';

    return {
      documentsLoaded: docs.length,
      indexedDocuments: indexedIds.length,
      totalChunks,
      indexStatus,
      lastActivity: this.lastActivity,
    };
  }

  /** Get all chunks for a document. */
  getChunksForDocument(documentId: string): Chunk[] {
    return this.persistence.readJson<Chunk[]>(`${CHUNKS_DIR}/${documentId}.json`) ?? [];
  }

  /** Get all chunks across all (still existing) indexed documents. */
  getAllChunks(): Chunk[] {
    const docIds = new Set(this.readDocs().map(d => d.id));
    return Object.keys(this.readMeta())
      .filter(id => docIds.has(id))
      .flatMap(id => this.getChunksForDocument(id));
  }

  /**
   * Split a document into chunks of ~CHUNK_SIZE characters at paragraph boundaries.
   * Paragraphs longer than CHUNK_SIZE are split at sentence, then word boundaries.
   */
  chunkDocument(documentId: string, content: string): Chunk[] {
    const pieces = content
      .replace(/\r\n/g, '\n')
      .split(/\n\s*\n/)
      .map(p => p.trim())
      .filter(p => p.length > 0)
      .flatMap(p => splitLong(p, CHUNK_SIZE));

    const chunks: Chunk[] = [];
    let buffer = '';
    for (const piece of pieces) {
      if (buffer && buffer.length + 2 + piece.length > CHUNK_SIZE) {
        chunks.push(this.createChunk(documentId, chunks.length, buffer));
        buffer = piece;
      } else {
        buffer += (buffer ? '\n\n' : '') + piece;
      }
    }
    if (buffer) chunks.push(this.createChunk(documentId, chunks.length, buffer));
    return chunks;
  }

  private createChunk(documentId: string, index: number, content: string): Chunk {
    return {
      id: uuidv4(),
      documentId,
      content,
      index,
      metadata: {
        charCount: String(content.length),
        wordCount: String(content.split(/\s+/).filter(Boolean).length),
      },
    };
  }

  private readDocs(): Document[] {
    return this.persistence.readJson<Document[]>(DOCUMENTS_META) ?? [];
  }

  private readMeta(): IndexMeta {
    return this.persistence.readJson<IndexMeta>(INDEX_META) ?? {};
  }
}

/** Break text longer than max into pieces <= max, preferring sentence then word boundaries. */
function splitLong(text: string, max: number): string[] {
  if (text.length <= max) return [text];
  const out: string[] = [];
  let rest = text;
  while (rest.length > max) {
    const window = rest.slice(0, max);
    let cut = Math.max(window.lastIndexOf('. '), window.lastIndexOf('\n'));
    if (cut < max / 2) cut = window.lastIndexOf(' ');
    if (cut <= 0) cut = max - 1;
    out.push(rest.slice(0, cut + 1).trim());
    rest = rest.slice(cut + 1).trim();
  }
  if (rest) out.push(rest);
  return out;
}

